import java.util.*;

class Solution {
    public long countCopies(String text, String word) {
        int m = word.length();
        long[] dp = new long[m + 1];   // dp[j] = ways to pick word[0..j-1] so far
        dp[0] = 1;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            for (int j = m; j >= 1; j--) {               // right-to-left: use c once per copy
                if (word.charAt(j - 1) == c) dp[j] += dp[j - 1];
            }
        }
        return dp[m];
    }
}

