class Solution:
    def countCopies(self, text: str, word: str) -> int:
        m = len(word)
        dp = [1] + [0] * m
        for c in text:
            for j in range(m, 0, -1):
                if word[j - 1] == c:
                    dp[j] += dp[j - 1]
        return dp[m]

